import base64
import struct

b64_data = ""

data = base64.b64decode(b64_data)
# Each cell might be represented by 3 integers (12 bytes) or more?
# Let's decode as 16-bit integers and print a few to see the pattern.
ints = struct.unpack(f"<{len(data)//2}h", data)

cells = []
# Assuming 3x 16-bit ints per cell?
for i in range(0, 100, 4):
    print(f"cell: {ints[i]}, {ints[i+1]}, {ints[i+2]}, {ints[i+3]}")
